import { z } from 'zod';
import type { JsonValue } from '../client';

export function validatePrefixItems(
	values: JsonValue[],
	prefixValidators: readonly ((value: JsonValue) => boolean)[],
	restValidator: ((value: JsonValue) => boolean) | undefined,
	minimum: number,
	maximum: number | undefined,
	ctx: z.RefinementCtx,
): void {
	if (values.length < minimum)
		ctx.addIssue({
			code: 'too_small',
			origin: 'array',
			minimum,
			inclusive: true,
			input: values,
		});
	if (maximum !== undefined && values.length > maximum)
		ctx.addIssue({
			code: 'too_big',
			origin: 'array',
			maximum,
			inclusive: true,
			input: values,
		});
	for (let index = 0; index < values.length; index += 1) {
		const validator =
			index < prefixValidators.length ? prefixValidators[index] : restValidator;
		const value = values[index];
		if (validator && value !== undefined && !validator(value))
			ctx.addIssue({
				code: 'custom',
				path: [index],
				message: 'Array item does not match the documented tuple schema',
			});
	}
}

export function jsonValuesEqual(left: JsonValue, right: JsonValue): boolean {
	if (left === right) return true;
	if (Array.isArray(left) && Array.isArray(right))
		return (
			left.length === right.length &&
			left.every(
				(value, index) =>
					right[index] !== undefined && jsonValuesEqual(value, right[index]),
			)
		);
	if (
		left !== null &&
		right !== null &&
		typeof left === 'object' &&
		typeof right === 'object' &&
		!Array.isArray(left) &&
		!Array.isArray(right)
	) {
		const leftKeys = Object.keys(left).sort();
		const rightKeys = Object.keys(right).sort();
		return (
			leftKeys.length === rightKeys.length &&
			leftKeys.every((key, index) => {
				const rightKey = rightKeys[index];
				const leftValue = left[key];
				const rightValue = right[key];
				return (
					rightKey !== undefined &&
					leftValue !== undefined &&
					rightValue !== undefined &&
					key === rightKey &&
					jsonValuesEqual(leftValue, rightValue)
				);
			})
		);
	}
	return false;
}

function matchesObjectKeywords(
	value: JsonValue,
	required: readonly string[],
	minimum: number | undefined,
	maximum: number | undefined,
): boolean {
	if (value === null || typeof value !== 'object' || Array.isArray(value))
		return true;
	const keys = Object.keys(value);
	return (
		required.every((key) => Object.hasOwn(value, key)) &&
		(minimum === undefined || keys.length >= minimum) &&
		(maximum === undefined || keys.length <= maximum)
	);
}

